def transform(grid):
    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    for r, row in enumerate(grid):
        for c in range(len(row) - 2):
            if row[c] != bg and row[c + 2] == row[c] and row[c + 1] == bg:
                out[r][c + 1] = 2
    return out
